'use strict';

// 合同：unitPriceCents 与 quantity 都必须是非负整数，
// 返回 unitPriceCents * quantity，单位仍为分。
function assertNonNegativeInteger(value, name) {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError(name + ' 必须是非负整数，收到：' + value);
  }
}

function totalCents(unitPriceCents, quantity) {
  assertNonNegativeInteger(unitPriceCents, 'unitPriceCents');
  assertNonNegativeInteger(quantity, 'quantity');
  return unitPriceCents * quantity;
}

module.exports = { totalCents };

'use strict';

const assert = require('node:assert/strict');
const { totalCents } = require('../money');

function checkNormalTotal() {
  assert.strictEqual(totalCents(250, 4), 1000, '4 件、单价 250 分应得到 1000 分');
}

function checkZeroQuantity() {
  assert.strictEqual(totalCents(250, 0), 0, '数量为 0 时总金额应为 0');
}

function checkZeroUnitPrice() {
  assert.strictEqual(totalCents(0, 5), 0, '单价为 0 时总金额应为 0');
}

function checkNegativeQuantityThrows() {
  assert.throws(
    () => totalCents(250, -1),
    RangeError,
    '负数量应触发 RangeError'
  );
}

function checkFractionalQuantityThrows() {
  assert.throws(
    () => totalCents(250, 1.5),
    RangeError,
    '小数数量应触发 RangeError'
  );
}

function runAllChecks() {
  const checks = [
    ['普通数量', checkNormalTotal],
    ['零数量', checkZeroQuantity],
    ['零单价', checkZeroUnitPrice],
    ['负数量抛出 RangeError', checkNegativeQuantityThrows],
    ['小数数量抛出 RangeError', checkFractionalQuantityThrows],
  ];

  for (const [name, check] of checks) {
    check();
    console.log('已通过：' + name);
  }

  return checks.length;
}

module.exports = { runAllChecks };

'use strict';

const { runAllChecks } = require('./checks/money.checks');

function main() {
  const passed = runAllChecks();
  console.log('全部 ' + passed + ' 项断言通过');
}

main();
